### Config
```terraform
# create a scoped variable
resource "octopusdeploy_variable" "scoped_variable" {
    owner_id = local.project_id
    type = "String"
    name = "My Scoped Variable (OK to Delete)"
    scope {
        environments = ["Environments-401" ,"Environments-82", "Environments-141"]
    }
    value = "ScopedValue"
}

data "octopusdeploy_variables" "variable_to_find" {
  space_id = resource.octopusdeploy_variable.scoped_variable.space_id
  owner_id = resource.octopusdeploy_variable.scoped_variable.owner_id
  name = resource.octopusdeploy_variable.scoped_variable.name
  scope {
    environments = resource.octopusdeploy_variable.scoped_variable.scope[0].environments
  }

  depends_on = [ resource.octopusdeploy_variable.scoped_variable ]
}
```

